# EXPLORATORY (non-binding; does not change any S6 verdict): which feature family carries the M1b gain over the tier-only base rate?
suppressMessages({ library(data.table); library(jsonlite) }); source("scripts/w2r1/s6_fit_eval.R", local = FALSE)
ex <- list()
for (pos in c("QB", "RB", "WR", "TE")) { d <- T[position == pos]; fit <- d[split == "FIT"]; val <- d[split == "VAL"]; yv <- val$lab_primary; tr <- fit[, .(r = (sum(lab_primary) + 1) / (.N + 2)), by = tier]; M0 <- tr$r[match(val$tier, tr$tier)]; B0 <- mean((M0 - yv)^2)
  sets <- list(tier_only_logit = c("tier_starter", "tier_flex"), tier_plus_LEVEL = c("tier_starter", "tier_flex", LV[[pos]]), plus_TREND = c("tier_starter", "tier_flex", LV[[pos]], TR), plus_CONTEXT = c("tier_starter", "tier_flex", LV[[pos]], CX), M1b_all = c("tier_starter", "tier_flex", TR, LV[[pos]], CX), TREND_only_over_tier = c("tier_starter", "tier_flex", TR), CONTEXT_only_over_tier = c("tier_starter", "tier_flex", CX))
  r <- lapply(sets, function(cols) { best <- NULL; for (lam in c(100, 10, 1, 0.1)) { Xtr <- as.matrix(fit[, ..cols]); ok <- complete.cases(Xtr); mu <- colMeans(Xtr[ok, , drop = FALSE]); sdv <- pmax(apply(Xtr[ok, , drop = FALSE], 2, sd), 1e-9); m <- fit_logit(sweep(sweep(Xtr[ok, , drop = FALSE], 2, mu), 2, sdv, "/"), fit$lab_primary[ok], lam); Xv <- as.matrix(val[, ..cols]); okv <- complete.cases(Xv); p <- M0; p[okv] <- plogis(m$a0 + as.vector(sweep(sweep(Xv[okv, , drop = FALSE], 2, mu), 2, sdv, "/") %*% m$beta)); p <- pmin(pmax(p, 1e-3), 1 - 1e-3); l <- -mean(yv * log(p) + (1 - yv) * log(1 - p)); if (is.null(best) || l < best$l) best <- list(l = l, brier = mean((p - yv)^2), lam = lam) }; list(brier_skill_vs_M0 = 1 - best$brier / B0, logloss = best$l) })
  ex[[pos]] <- r; cat(sprintf("%s: %s\n", pos, paste(sprintf("%s %+.3f", names(r), sapply(r, `[[`, "brier_skill_vs_M0")), collapse = " | "))) }
write_json(list(note = "EXPLORATORY ablation of the M1b gain (VAL, FIT-trained, lambda chosen per set on VAL log loss); non-binding", ablation = ex), "scripts/w2r1/results/s6_explore.json", auto_unbox = TRUE, pretty = TRUE, digits = 4)
